package sn.ucad.nexora.espace.application.service;
import java.util.List; import java.util.UUID; import org.springframework.stereotype.Service; import sn.ucad.nexora.espace.application.usecase.GetEspaceUseCase; import sn.ucad.nexora.espace.domain.entity.EspaceProfessionnel; import sn.ucad.nexora.espace.domain.repository.EspaceRepository; import sn.ucad.nexora.espace.infrastructure.persistence.UtilisateurLookupRepository;
@Service public class GetEspaceService implements GetEspaceUseCase{private final EspaceRepository e;private final UtilisateurLookupRepository u;public GetEspaceService(EspaceRepository e,UtilisateurLookupRepository u){this.e=e;this.u=u;}public EspaceProfessionnel get(Long id){return e.findById(id).orElseThrow(()->new IllegalArgumentException("Espace introuvable"));}public List<EspaceProfessionnel> mine(UUID accountId){Long id=u.findIdByAccountId(accountId).orElseThrow(()->new IllegalArgumentException("Profil utilisateur introuvable"));return e.findByUtilisateurId(id);}}
